import{_ as n}from"./plugin-vue_export-helper-c27b6911.js";import{o as s,c as a,e}from"./app-26293047.js";const t={},c=e(`<h1 id="emscripten-把-c-c-编译为-webassembly-javascript" tabindex="-1"><a class="header-anchor" href="#emscripten-把-c-c-编译为-webassembly-javascript" aria-hidden="true">#</a> emscripten（把 C/C++ 编译为 WebAssembly/JavaScript）</h1><blockquote><p>Homebrew 版本 4.0.21 ｜ 主页：见官方文档 ｜ 安装：<code>brew install emscripten</code></p></blockquote><h2 id="一、它是什么" tabindex="-1"><a class="header-anchor" href="#一、它是什么" aria-hidden="true">#</a> 一、它是什么</h2><p>Emscripten 是一个完整的 LLVM-to-WebAssembly 编译工具链，能把 C/C++ 源码直接编译成可以在浏览器、Node.js 或其他 JavaScript 运行时中运行的 WebAssembly（<code>.wasm</code>）二进制文件和配套的 JavaScript 胶水代码。它解决的核心问题是：让海量的 C/C++ 遗产代码和成熟库（如 SDL、OpenGL、zlib、SQLite）无需重写就能跑在 Web 平台上。典型应用场景包括把游戏引擎、音视频处理、图像识别、密码学库等高性能模块编译为 wasm，在浏览器中实现接近原生的性能。</p><h2 id="二、安装与升级" tabindex="-1"><a class="header-anchor" href="#二、安装与升级" aria-hidden="true">#</a> 二、安装与升级</h2><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 安装</span>
brew <span class="token function">install</span> emscripten

<span class="token comment"># 升级到最新版本</span>
brew upgrade emscripten

<span class="token comment"># 卸载</span>
brew uninstall emscripten

<span class="token comment"># 验证安装成功（打印版本号）</span>
emcc <span class="token parameter variable">--version</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>验证输出类似：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>emcc <span class="token punctuation">(</span>Emscripten gcc/clang-like replacement + linker emulating GNU ld<span class="token punctuation">)</span> <span class="token number">4.0</span>.21 <span class="token punctuation">(</span>4e14c0e2c47ddb60d62ebc1839cc2a7eef94daf2<span class="token punctuation">)</span>
Copyright <span class="token punctuation">(</span>C<span class="token punctuation">)</span> <span class="token number">2014</span> the Emscripten authors <span class="token punctuation">(</span>see AUTHORS.txt<span class="token punctuation">)</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>同时可以确认 WebAssembly 支持情况：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 确认 clang 与 wasm 后端可用</span>
emcc <span class="token parameter variable">-v</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="三、常用命令速查" tabindex="-1"><a class="header-anchor" href="#三、常用命令速查" aria-hidden="true">#</a> 三、常用命令速查</h2><table><thead><tr><th>命令</th><th>参数说明</th><th>示例</th></tr></thead><tbody><tr><td><code>emcc</code></td><td>主编译命令（编译 C 源码）</td><td><code>emcc hello.c -o hello.html</code></td></tr><tr><td><code>em++</code></td><td>编译 C++ 源码（等价于 emcc 的 C++ 版本）</td><td><code>em++ main.cpp -o main.js</code></td></tr><tr><td><code>-O0 / -O1 / -O2 / -O3</code></td><td>优化级别，O3 体积与性能较均衡</td><td><code>emcc -O3 code.c -o code.wasm</code></td></tr><tr><td><code>-s</code></td><td>设置链接/编译选项，如 <code>-s WASM=1</code></td><td><code>emcc main.c -s WASM=1 -o main.js</code></td></tr><tr><td><code>-o</code></td><td>指定输出文件，扩展名决定产物类型</td><td><code>emcc a.c -o a.html</code> / <code>-o a.js</code> / <code>-o a.wasm</code></td></tr><tr><td><code>--bind</code></td><td>启用 embind（把 C++ 类/函数导出给 JS 调用）</td><td><code>em++ --bind api.cpp -o api.js</code></td></tr><tr><td><code>-I</code> / <code>-L</code> / <code>-l</code></td><td>指定头文件路径、库路径、链接库</td><td><code>emcc main.c -Iinclude -lmylib -o out.js</code></td></tr><tr><td><code>-sEXPORTED_FUNCTIONS</code></td><td>显式导出指定函数供 JS 调用</td><td><code>-sEXPORTED_FUNCTIONS=_add</code></td></tr><tr><td><code>-sMODULARIZE=1</code></td><td>生成模块化代码，便于按需加载</td><td><code>-sMODULARIZE=1 -sEXPORT_NAME=MyModule</code></td></tr><tr><td><code>emrun</code></td><td>运行生成 HTML 的本地测试服务器</td><td><code>emrun --port 8080 index.html</code></td></tr></tbody></table><h2 id="四、实际示例" tabindex="-1"><a class="header-anchor" href="#四、实际示例" aria-hidden="true">#</a> 四、实际示例</h2><h3 id="示例-1-编译-c-为-html-在浏览器中运行" tabindex="-1"><a class="header-anchor" href="#示例-1-编译-c-为-html-在浏览器中运行" aria-hidden="true">#</a> 示例 1：编译 C 为 HTML，在浏览器中运行</h3><p>准备一个 C 文件 <code>hello.c</code>：</p><div class="language-c line-numbers-mode" data-ext="c"><pre class="language-c"><code><span class="token macro property"><span class="token directive-hash">#</span><span class="token directive keyword">include</span> <span class="token string">&lt;stdio.h&gt;</span></span>
<span class="token macro property"><span class="token directive-hash">#</span><span class="token directive keyword">include</span> <span class="token string">&lt;emscripten.h&gt;</span></span>

<span class="token keyword">int</span> <span class="token function">main</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token function">printf</span><span class="token punctuation">(</span><span class="token string">&quot;Hello, WebAssembly!\\n&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token keyword">return</span> <span class="token number">0</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>编译生成 HTML：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>emcc hello.c <span class="token parameter variable">-o</span> hello.html
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>用 emrun 启动本地服务器并打开页面，打开浏览器开发者工具（F12）Console 即可看到 <code>Hello, WebAssembly!</code> 输出：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>emrun <span class="token parameter variable">--port</span> <span class="token number">8080</span> hello.html
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><h3 id="示例-2-编译为独立-wasm-并在-node-js-中调用导出函数" tabindex="-1"><a class="header-anchor" href="#示例-2-编译为独立-wasm-并在-node-js-中调用导出函数" aria-hidden="true">#</a> 示例 2：编译为独立 wasm 并在 Node.js 中调用导出函数</h3><p>准备 <code>math.c</code>，声明一个可供 JS 调用的函数：</p><div class="language-c line-numbers-mode" data-ext="c"><pre class="language-c"><code><span class="token macro property"><span class="token directive-hash">#</span><span class="token directive keyword">include</span> <span class="token string">&lt;emscripten.h&gt;</span></span>

EMSCRIPTEN_KEEPALIVE
<span class="token keyword">int</span> <span class="token function">add</span><span class="token punctuation">(</span><span class="token keyword">int</span> a<span class="token punctuation">,</span> <span class="token keyword">int</span> b<span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">return</span> a <span class="token operator">+</span> b<span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>编译时导出该函数：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>emcc math.c <span class="token parameter variable">-o</span> math.js <span class="token parameter variable">-sEXPORTED_FUNCTIONS</span><span class="token operator">=</span>_add <span class="token parameter variable">-sEXPORTED_RUNTIME_METHODS</span><span class="token operator">=</span>ccall,cwrap
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>在 Node.js 中调用：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">node</span> <span class="token parameter variable">-e</span> <span class="token string">&quot;
const m = require(&#39;./math.js&#39;);
const add = m.cwrap(&#39;add&#39;, &#39;number&#39;, [&#39;number&#39;, &#39;number&#39;]);
console.log(&#39;1 + 2 =&#39;, add(1, 2));
&quot;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>输出：<code>1 + 2 = 3</code></p><h3 id="示例-3-编译-c-并用-embind-导出类给-javascript" tabindex="-1"><a class="header-anchor" href="#示例-3-编译-c-并用-embind-导出类给-javascript" aria-hidden="true">#</a> 示例 3：编译 C++ 并用 embind 导出类给 JavaScript</h3><p>准备 <code>greet.cpp</code>：</p><div class="language-cpp line-numbers-mode" data-ext="cpp"><pre class="language-cpp"><code><span class="token macro property"><span class="token directive-hash">#</span><span class="token directive keyword">include</span> <span class="token string">&lt;emscripten/bind.h&gt;</span></span>
<span class="token macro property"><span class="token directive-hash">#</span><span class="token directive keyword">include</span> <span class="token string">&lt;string&gt;</span></span>

<span class="token keyword">class</span> <span class="token class-name">Greeter</span> <span class="token punctuation">{</span>
<span class="token keyword">public</span><span class="token operator">:</span>
    <span class="token function">Greeter</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">:</span> <span class="token function">name_</span><span class="token punctuation">(</span><span class="token string">&quot;world&quot;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span><span class="token punctuation">}</span>
    <span class="token keyword">void</span> <span class="token function">setName</span><span class="token punctuation">(</span><span class="token keyword">const</span> std<span class="token double-colon punctuation">::</span>string<span class="token operator">&amp;</span> n<span class="token punctuation">)</span> <span class="token punctuation">{</span> name_ <span class="token operator">=</span> n<span class="token punctuation">;</span> <span class="token punctuation">}</span>
    std<span class="token double-colon punctuation">::</span>string <span class="token function">greet</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">const</span> <span class="token punctuation">{</span> <span class="token keyword">return</span> <span class="token string">&quot;Hello, &quot;</span> <span class="token operator">+</span> name_ <span class="token operator">+</span> <span class="token string">&quot;!&quot;</span><span class="token punctuation">;</span> <span class="token punctuation">}</span>
<span class="token keyword">private</span><span class="token operator">:</span>
    std<span class="token double-colon punctuation">::</span>string name_<span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">;</span>

<span class="token function">EMSCRIPTEN_BINDINGS</span><span class="token punctuation">(</span>greeter<span class="token punctuation">)</span> <span class="token punctuation">{</span>
    emscripten<span class="token double-colon punctuation">::</span><span class="token generic-function"><span class="token function">class_</span><span class="token generic class-name"><span class="token operator">&lt;</span>Greeter<span class="token operator">&gt;</span></span></span><span class="token punctuation">(</span><span class="token string">&quot;Greeter&quot;</span><span class="token punctuation">)</span>
        <span class="token punctuation">.</span><span class="token generic-function"><span class="token function">constructor</span><span class="token generic class-name"><span class="token operator">&lt;</span><span class="token operator">&gt;</span></span></span><span class="token punctuation">(</span><span class="token punctuation">)</span>
        <span class="token punctuation">.</span><span class="token function">function</span><span class="token punctuation">(</span><span class="token string">&quot;setName&quot;</span><span class="token punctuation">,</span> <span class="token operator">&amp;</span>Greeter<span class="token double-colon punctuation">::</span>setName<span class="token punctuation">)</span>
        <span class="token punctuation">.</span><span class="token function">function</span><span class="token punctuation">(</span><span class="token string">&quot;greet&quot;</span><span class="token punctuation">,</span> <span class="token operator">&amp;</span>Greeter<span class="token double-colon punctuation">::</span>greet<span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>编译：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>em++ greet.cpp <span class="token parameter variable">-o</span> greet.js <span class="token parameter variable">--bind</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>在 Node.js 中调用：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">node</span> <span class="token parameter variable">-e</span> <span class="token string">&quot;
require(&#39;./greet.js&#39;).then(m =&gt; {
    const g = new m.Greeter();
    g.setName(&#39;Emscripten&#39;);
    console.log(g.greet());
});
&quot;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>输出：<code>Hello, Emscripten!</code></p><h2 id="五、进阶技巧与配置" tabindex="-1"><a class="header-anchor" href="#五、进阶技巧与配置" aria-hidden="true">#</a> 五、进阶技巧与配置</h2><ol><li><p><strong>模块化加载</strong>：默认生成的 JS 会立即自执行，不利于现代前端打包。建议用 <code>-sMODULARIZE=1 -sEXPORT_NAME=MyModule</code> 生成可 Promise 加载的模块，前端配合 <code>Webpack</code>/<code>Vite</code> 使用时更顺手：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>emcc main.c <span class="token parameter variable">-o</span> main.js <span class="token parameter variable">-sMODULARIZE</span><span class="token operator">=</span><span class="token number">1</span> <span class="token parameter variable">-sEXPORT_NAME</span><span class="token operator">=</span>MyModule
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div></li><li><p><strong>定制内存初始化文件</strong>：大型 C/C++ 项目会生成 <code>.data</code> 内存初始化文件，前端部署时务必与 <code>.wasm</code>、<code>.js</code> 一同拷贝，并设置正确的 <code>-sSINGLE_FILE=1</code> 可将一切内联进单个 JS 文件方便分发：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>emcc main.c <span class="token parameter variable">-o</span> main.js <span class="token parameter variable">-sSINGLE_FILE</span><span class="token operator">=</span><span class="token number">1</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div></li><li><p><strong>与 CMake 集成</strong>：设置 <code>CMAKE_TOOLCHAIN_FILE</code> 即可用 CMake 原生构建 Emscripten 项目，无需手写 emcc 命令：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>cmake <span class="token parameter variable">-DCMAKE_TOOLCHAIN_FILE</span><span class="token operator">=</span><span class="token variable">$EMSDK</span>/upstream/emscripten/cmake/Modules/Platform/Emscripten.cmake <span class="token parameter variable">-DCMAKE_BUILD_TYPE</span><span class="token operator">=</span>Release <span class="token punctuation">..</span>
<span class="token function">make</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>其中 <code>$EMSDK</code> 是 Emscripten SDK 根目录（Homebrew 安装路径通常为 <code>/opt/homebrew/Cellar/emscripten/&lt;版本&gt;/</code>，可用 <code>which emcc</code> 定位）。</p></li><li><p><strong>常用环境变量</strong>：通过 <code>EMCC_DEBUG=1</code> 可输出详细编译日志排查问题；<code>EMCC_FORCE_STDLIBS=1</code> 可强制使用标准库版本。</p></li></ol><h2 id="六、注意事项与常见问题" tabindex="-1"><a class="header-anchor" href="#六、注意事项与常见问题" aria-hidden="true">#</a> 六、注意事项与常见问题</h2><ol><li><p><strong>文件系统差异</strong>：浏览器中的 wasm 运行在虚拟文件系统（MEMFS）中，<code>fopen</code>/<code>fread</code> 无法直接读取服务器上的真实文件。需要先把文件预加载到虚拟文件系统，常用 <code>--preload-file</code> 或 <code>--embed-file</code> 选项，或通过 JS 侧读取后再传入。</p></li><li><p><strong>函数导出缺失导致调用为 undefined</strong>：JS 只能调用显式导出的函数。忘记加 <code>EMSCRIPTEN_KEEPALIVE</code> 或 <code>-sEXPORTED_FUNCTIONS</code>，直接调用会报 <code>undefined is not a function</code>。导出时注意 C 函数名前加下划线（<code>_add</code>）。</p></li><li><p><strong>性能与体积权衡</strong>：默认未优化时 wasm 体积大、性能差。发布前务必加 <code>-O3</code>；若追求极致体积可用 <code>-Os</code>。调试时用 <code>-O0 -g4</code> 保留符号便于定位错误。</p></li><li><p><strong>依赖系统库的问题</strong>：有些 C/C++ 库依赖 POSIX 或系统特性，Emscripten 未完全实现（如 fork、部分网络 API、多线程），移植前先确认目标库是否支持 wasm。启用多线程需要 <code>-sPTHREADS=1</code> 并配合 <code>SharedArrayBuffer</code>（需站点开启跨域隔离头）。</p></li><li><p><strong>Node 版本兼容</strong>：生成的 JS 可能在较老 Node 版本上无法运行，建议使用 Node.js 16+；浏览器端注意 wasm 的 MIME 类型需配置为 <code>application/wasm</code> 才可正常加载。</p></li><li><p><strong>升级后缓存失效</strong>：升级 Homebrew 的 emscripten 后，旧的 <code>.wasm</code>/<code>.data</code> 缓存可能不兼容，务必全量重新编译，避免混用不同版本产物导致的崩溃。</p></li></ol>`,40),o=[c];function p(d,i){return s(),a("div",null,o)}const u=n(t,[["render",p],["__file","emscripten.html.vue"]]);export{u as default};
